namespace pcnet {
namespace {
struct ImageAccum { std::set<std::uint32_t> points; std::vector<const MeasureRecord *> measures; std::set<std::uint32_t> neighbors; };
std::string quote(const std::string &value) { std::string out = "\""; for (char c : value) { if (c == '"') out += "\\\""; else out += c; } return out + "\""; }
std::vector<double> occupancy(const std::vector<std::pair<double,double>> &intervals, double lo, double hi, std::uint32_t bins) {
  std::vector<double> result(bins, 0.0); if (intervals.empty() || hi <= lo) return result;
  for (std::uint32_t b = 0; b < bins; ++b) { const double left = lo + (hi - lo) * b / bins, right = lo + (hi - lo) * (b + 1) / bins; for (const auto &[start,end] : intervals) if (std::max(start,left) <= std::min(end,right) && (end > start || (start >= left && start <= right))) { result[b] = 1.0; break; } }
  return result;
}
std::pair<double,double> envelope(const std::vector<const MeasureRecord *> &measures) {
  double lo = std::numeric_limits<double>::infinity(), hi = -std::numeric_limits<double>::infinity(); for (auto *m : measures) for (const auto &i : m->timing.intervals) { lo = std::min(lo, i.start); hi = std::max(hi, i.end); } return {lo,hi};
}
double max_gap(const std::vector<const MeasureRecord *> &measures) {
  std::vector<std::pair<double,double>> intervals; for (auto *m : measures) for (const auto &i : m->timing.intervals) intervals.emplace_back(i.start,i.end); if (intervals.size()<2) return 0.0; std::sort(intervals.begin(), intervals.end()); double cursor=intervals.front().second, gap=0.0; for (std::size_t i=1;i<intervals.size();++i) { gap=std::max(gap, intervals[i].first-cursor); cursor=std::max(cursor,intervals[i].second); } return gap;
}
double measure_span(const std::vector<double> &values) { if (values.size() < 2) return 0.0; auto [lo, hi] = std::minmax_element(values.begin(), values.end()); return *hi - *lo; }
std::uint64_t component_count(const std::vector<std::set<std::uint32_t>> &adj) { std::vector<bool> seen(adj.size()); std::uint64_t count=0; for (std::uint32_t start=0; start<adj.size(); ++start) if (!seen[start]) { ++count; std::queue<std::uint32_t> q; q.push(start); seen[start]=true; while(!q.empty()) { auto n=q.front(); q.pop(); for(auto v:adj[n]) if(!seen[v]) {seen[v]=true;q.push(v);} } } return count; }
}
QualityReport evaluate_quality(const NetworkView &view, const QualityConfig &config) {
  if (!validate_time_bins(config.time_bins)) throw std::invalid_argument("time_bins must be between 4 and 32");
  QualityReport report; report.metadata.time_bins=config.time_bins; report.metadata.denominator="active measures and valid exposure interval union"; report.metadata.coordinate_rule="sample bins per atomic image; ground overlap unavailable in core";
  std::vector<ImageAccum> accum(view.images.size());
  for (const auto &m:view.measures) if (!(m.state_flags&kStateDisabled) && m.image_index<accum.size()) { accum[m.image_index].points.insert(m.point_index); accum[m.image_index].measures.push_back(&m); }
  for (const auto &point:view.points) { std::set<std::uint32_t> images; for(const auto&m:view.measures) if(!(m.state_flags&kStateDisabled)&&m.point_index==point.point_index) images.insert(m.image_index); for(auto a:images) for(auto b:images) if(a!=b) accum[a].neighbors.insert(b); }
  for(std::uint32_t i=0;i<view.images.size();++i) { auto &a=accum[i]; ImageQuality q; q.image_index=i;q.n_points=a.points.size();q.n_measures=a.measures.size();q.n_neighbors=a.neighbors.size(); auto [lo,hi]=envelope(a.measures); std::vector<std::pair<double,double>> intervals; std::vector<double> samples; std::size_t start=0,mid=0,end=0; for(auto*m:a.measures){for(auto&x:m->timing.intervals)intervals.emplace_back(x.start,x.end);samples.push_back(m->sample); if(std::isfinite(lo)&&hi>lo&&!m->timing.intervals.empty()){auto moments=temporal_moments(m->timing); double tau=2*(moments.mean-lo)/(hi-lo)-1; if(tau<-1.0/3)++start; else if(tau<=1.0/3)++mid; else ++end;}} q.time_bins=occupancy(intervals,lo,hi,config.time_bins); q.time_coverage=q.time_bins.empty()?0.0:std::accumulate(q.time_bins.begin(),q.time_bins.end(),0.0)/q.time_bins.size(); q.max_time_gap=max_gap(a.measures); if(!samples.empty()){auto [slo,shi]=std::minmax_element(samples.begin(),samples.end()); q.cross_track_bins=occupancy({{*slo,*shi}},*slo,*shi,config.time_bins); q.cross_track_coverage=q.cross_track_bins.empty()?0.0:std::accumulate(q.cross_track_bins.begin(),q.cross_track_bins.end(),0.0)/q.cross_track_bins.size();} const double denom=a.measures.empty()?1.0:a.measures.size(); q.start_coverage=start/denom;q.middle_coverage=mid/denom;q.end_coverage=end/denom;q.sparse=q.n_points<config.sparse_point_threshold;if(q.sparse)q.warning_flags.push_back("sparse"); NetworkView unit=view;unit.measures.clear();for(auto*m:a.measures)unit.measures.push_back(*m);auto model=analyze_model(unit,config.model,ModelConfig{config.time_bins});q.design_rank=model.rank;q.condition_number=model.condition_number;if(model.unavailable_measures)q.warning_flags.push_back("time_unavailable"); report.images.push_back(std::move(q)); }
  std::map<std::pair<std::uint32_t,std::uint32_t>,std::set<std::uint32_t>> shared; for(const auto&point:view.points){std::set<std::uint32_t> images;for(const auto&m:view.measures)if(!(m.state_flags&kStateDisabled)&&m.point_index==point.point_index)images.insert(m.image_index);for(auto a=images.begin();a!=images.end();++a)for(auto b=std::next(a);b!=images.end();++b)shared[{*a,*b}].insert(point.point_index);}
  for(const auto &[key,points]:shared){PairQuality q;q.image_a=key.first;q.image_b=key.second;q.n_valid_tracks=points.size();q.n_independent_tracks=points.size();q.overlap_fallback=true;q.warning_flags.push_back("overlap_fallback");std::vector<double>a,b;for(const auto&m:view.measures){if(points.count(m.point_index)&&m.image_index==key.first){a.push_back(m.line);}if(points.count(m.point_index)&&m.image_index==key.second){b.push_back(m.line);}}q.along_track_span=measure_span(a);q.cross_track_span=measure_span(b);report.pairs.push_back(std::move(q));}
  std::vector<std::set<std::uint32_t>> adj(view.images.size());for(const auto&q:report.pairs){adj[q.image_a].insert(q.image_b);adj[q.image_b].insert(q.image_a);}report.network.n_images=view.images.size();report.network.n_points=0;for(const auto&p:view.points)if(!(p.state_flags&kStateDisabled))++report.network.n_points;report.network.n_measures=0;for(const auto&m:view.measures)if(!(m.state_flags&kStateDisabled))++report.network.n_measures;report.network.n_components=component_count(adj);for(const auto&q:report.images)if(q.n_points<config.sparse_point_threshold)report.network.weak_images.push_back(q.image_index);for(const auto&point:view.points){std::uint64_t count=0;for(const auto&m:view.measures)if(!(m.state_flags&kStateDisabled)&&m.point_index==point.point_index)++count;report.network.point_count_quantiles.push_back(count);}std::sort(report.network.point_count_quantiles.begin(),report.network.point_count_quantiles.end());return report;
}
void write_quality_csv_json(const QualityReport &report,const std::filesystem::path &directory){std::filesystem::create_directories(directory);std::ofstream image_csv(directory/"image_quality.csv");image_csv<<"image_index,n_points,n_measures,n_neighbors,time_coverage,cross_track_coverage,max_time_gap,design_rank,condition_number,sparse\n";for(const auto&q:report.images)image_csv<<q.image_index<<','<<q.n_points<<','<<q.n_measures<<','<<q.n_neighbors<<','<<q.time_coverage<<','<<q.cross_track_coverage<<','<<q.max_time_gap<<','<<q.design_rank<<','<<q.condition_number<<','<<(q.sparse?1:0)<<'\n';std::ofstream json(directory/"network_quality.json");json<<"{\n  \"metadata\": {\"time_bins\": "<<report.metadata.time_bins<<", \"denominator\": "<<quote(report.metadata.denominator)<<"},\n  \"ImageQuality\": [\n";for(std::size_t i=0;i<report.images.size();++i){const auto&q=report.images[i];json<<"    {\"image_index\": "<<q.image_index<<", \"n_points\": "<<q.n_points<<", \"time_coverage\": "<<q.time_coverage<<", \"start_coverage\": "<<q.start_coverage<<", \"middle_coverage\": "<<q.middle_coverage<<", \"end_coverage\": "<<q.end_coverage<<"}"<<(i+1==report.images.size()?"\n":",\n");}json<<"  ],\n  \"PairQuality\": [\n";for(std::size_t i=0;i<report.pairs.size();++i){const auto&q=report.pairs[i];json<<"    {\"image_a\": "<<q.image_a<<", \"image_b\": "<<q.image_b<<", \"overlap_fallback\": "<<(q.overlap_fallback?"true":"false")<<", \"along_track_span\": "<<q.along_track_span<<"}"<<(i+1==report.pairs.size()?"\n":",\n");}json<<"  ],\n  \"NetworkQuality\": {\"n_images\": "<<report.network.n_images<<", \"n_points\": "<<report.network.n_points<<", \"n_measures\": "<<report.network.n_measures<<", \"n_components\": "<<report.network.n_components<<"}\n}\n";}
}
